sys_variable_value.value:
(function execute(inputs, outputs) {
    var processor = new AccessGovernanceRevokeProcessor();
    var result = processor.processRequest(
        inputs.userid + '',
        inputs.action + '',
        inputs.grouplist + '',
        inputs.requestedby + '',
        inputs.approvedby + '',
        inputs.accessgovernanceid + ''
    );
    outputs.result = JSON.stringify(result);
})(inputs, outputs);

